package com.yeyamo_mobile.api.feed_service.application;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.feed_service.application.port.*;import com.yeyamo_mobile.api.feed_service.domain.model.*;
class FeedProjectionCommandServiceTests{@Test void projectsContentAndInteractionAndInvalidatesCache(){MemoryProjection p=new MemoryProjection();CounterCache cache=new CounterCache();List<String>events=new ArrayList<>();FeedProjectionCommandService s=new FeedProjectionCommandService(p,cache,(t,id,c,payload)->events.add(t));UUID post=UUID.randomUUID();s.content("content.post.published",new FeedPost(post,"a1","text","PUBLIC","PUBLISHED",null,List.of(),List.of("travel"),Instant.now(),Instant.now()),"c");s.interaction("interaction.like.added",post,"u1","c");assertEquals(1,p.metric(post).likes());assertEquals(2,p.signals.get("u1:"+post));assertEquals(2,cache.invalidations);assertEquals(List.of("feed.post.projected","feed.metrics.updated"),events);}
 static class MemoryProjection implements FeedProjectionPort{final Map<UUID,FeedPost>posts=new HashMap<>();final Map<UUID,FeedMetric>metrics=new HashMap<>();final Map<String,Double>signals=new HashMap<>();public void savePost(FeedPost p){posts.put(p.postId(),p);}public Optional<FeedPost>findPost(UUID id){return Optional.ofNullable(posts.get(id));}public FeedMetric metric(UUID id){return metrics.getOrDefault(id,FeedMetric.empty(id));}public void saveMetric(FeedMetric m){metrics.put(m.postId(),m);}public void adjustSignal(String u,UUID p,double w){signals.merge(u+":"+p,w,Double::sum);}public List<FeedCandidate>candidates(int l){return posts.values().stream().map(v->new FeedCandidate(v,metric(v.postId()))).toList();}public Map<String,Double>authorAffinities(String u){return Map.of();}}
 static class CounterCache implements FeedCachePort{int invalidations;public Optional<FeedPage>get(String u,int p,int s){return Optional.empty();}public void put(FeedPage p){}public void invalidate(){invalidations++;}}
}
